// The World on 26 November 2026 — make.fun news-image-20261126.
// Writes the entry image to $MAKEFUN_OUTPUT_DIR/entry.png (default /output).
// The image is embedded below as base64; this program only decodes it and
// writes it out. No network, no randomness: two runs write identical bytes.
// Built 26 Nov 2026: a cream broadsheet of Thursday 26 November 2026 —
// tariffs return on 14 partners, US growth 4.3% with PCE 3.8%, the Bank of
// Korea hikes to 3.25%, plus Hera's Dimorphos crater and nine more stories.

import * as fs from "node:fs";
import * as path from "node:path";

const PNG_SIGNATURE = Buffer.from([0x89, 0x50, 0x4e, 0x47, 0x0d, 0x0a, 0x1a, 0x0a]);

const IMAGE_BASE64 = "";

function main() {
  const bytes = Buffer.from(IMAGE_BASE64, "base64");
  if (bytes.length < 8 || !bytes.subarray(0, 8).equals(PNG_SIGNATURE)) {
    throw new Error("embedded image is not a valid PNG");
  }
  // IHDR chunk: width and height are big-endian uint32 at offsets 16 and 20.
  const width = bytes.readUInt32BE(16);
  const height = bytes.readUInt32BE(20);
  if (width !== 1024 || height !== 1024) {
    throw new Error("embedded image is not 1024x1024");
  }
  const outDir = process.env.MAKEFUN_OUTPUT_DIR || "/output";
  fs.mkdirSync(outDir, { recursive: true });
  const outPath = path.join(outDir, "entry.png");
  fs.writeFileSync(outPath, bytes);
}

main();
